function resolveLocale(input) {
    if (!input)
        return exports.DEFAULT_LOCALE;
    const clean = input.trim().toLowerCase();
    if (clean.startsWith("pt"))
        return "pt-BR";
    return "en";
}
function formatLocaleNumber(value, locale = exports.DEFAULT_LOCALE) {
    return new Intl.NumberFormat(locale === "pt-BR" ? "pt-BR" : "en-US").format(value);
}
function createTranslator(locale = exports.DEFAULT_LOCALE) {
    const catalog = locale === "pt-BR" ? exports.ptBRCatalog : exports.enCatalog;
    return function t(key, vars) {
        const parts = key.split(".");
        let current = catalog;
        for (const part of parts) {
            if (current && typeof current === "object" && part in current) {
                current = current[part];
            }
            else {
                return key;
            }
        }
        if (typeof current !== "string") {
            return key;
        }
        if (vars) {
            return current.replace(/\{(\w+)\}/g, (_, k) => {
                return k in vars ? String(vars[k]) : `{${k}}`;
            });
        }
        return current;
    };
}
